// ── REFERENCE DERIVATIONS — Claudy: move these into owedBookService (Cluster 3) ──
// Shows exactly how each tab + the KPI tiles derive from the dataset above.

export const getPbmOptions = (): string[] =>
  Array.from(new Set(owedBookClaims.map(c => c.pbmName).filter(Boolean) as string[])).sort();

export const getKpis = (claims: OwedBookClaim[] = owedBookClaims) => ({
  commercialUnderpaid: +claims.filter(c => c.owed > 0).reduce((s, c) => s + c.owed, 0).toFixed(2),
  commercialScripts: claims.length,
  updatedDifference: +claims.reduce((s, c) => s + (c.updatedDifference ?? 0), 0).toFixed(2),
  owed: +claims.filter(c => c.owed > 0).reduce((s, c) => s + c.owed, 0).toFixed(2),
});

// Tab row shapers (the UI picks columns per UI_SPEC §5.3):
export const getCommercialRows = (c = owedBookClaims) => c;                       // Date·Script·Qty·MedicaidRate·Method·Expected·OrigPaid·Owed·Report·Status
export const getUpdatedRows = (c = owedBookClaims) =>
  c.filter(x => x.newPaid !== null);                                             // Date·Script·OrigPaid·NewPaid·UpdatedDiff
export const getFederalRows = (c = owedBookClaims) =>
  c.filter(x => x.federalExpected !== null);                                     // Date·Script·Qty·AAC·Expected·OrigPaid·Diff·Report

export interface OwedSummaryRow { pbmName: string; commercialDollars: number; federalDollars: number; }
export const getSummary = (claims: OwedBookClaim[] = owedBookClaims): OwedSummaryRow[] => {
  const m = new Map<string, OwedSummaryRow>();
  for (const c of claims) {
    if (!c.pbmName) continue;
    const r = m.get(c.pbmName) ?? { pbmName: c.pbmName, commercialDollars: 0, federalDollars: 0 };
    r.commercialDollars += c.owed > 0 ? c.owed : 0;
    r.federalDollars += (c.federalDiff && c.federalDiff > 0) ? c.federalDiff : 0;
    m.set(c.pbmName, r);
  }
  return Array.from(m.values())
    .map(r => ({ ...r, commercialDollars: +r.commercialDollars.toFixed(2), federalDollars: +r.federalDollars.toFixed(2) }))
    .sort((a, b) => b.commercialDollars - a.commercialDollars);
};
